catalog_script_client.script:
function onSubmit() {
	debugger;
	g_form.clearMessages();
	var commonName = g_form.getValue("subject_common_name");
	if (!isValidDNSOrIP(commonName)) {
		g_form.addErrorMessage(commonName + " Não é válido como um nome comum (CN) válido.");
		return false;
	}
	if (commonName.endsWith('bnb.gov.br')) {
		g_form.setValue("certificate_purpose", "external");
	} else if (commonName.endsWith('intra.bnb') ||
		commonName.endsWith('dmz.bnb') ||
		commonName.endsWith('dreads.bnb')) {
		g_form.setValue("certificate_purpose", "internal");
	} else {
		g_form.addErrorMessage("Nome comum (CN) do certificado inválido.");
		return false;
	}

	var newSAN = commonName;
	var san = g_form.getValue("subject_alternative_name").trim();
	if (san) {
		var regex = /(?:\d+:\s+)?#([a-fA-F0-9\s]{8,})/g;
		newSAN = san.replace(regex, function (match, hexWithSpaces) {
			var hex = (hexWithSpaces || '').replace(/\s+/g, '');
			if (hex.length === 8) {
				return hexToIPv4(hex);
			} else if (hex.length === 32) {
				return hexToIPv6(hex);
			}
			return match;
		});
		var sanArr = newSAN.split(',');
		for (var i in sanArr) {
			if (!isValidDNSOrIP(sanArr[i])) {
				g_form.addErrorMessage(sanArr[i] + " Não é válido como nome alternativo.");
				return false;
			}
		}
	}
	g_form.setValue("subject_alternative_name", newSAN);
	g_form.setValue("auto_renew_enabled", true);
}


function isValidDNSOrIP(name) {
	if (!name || typeof name !== 'string') return false;

	name = name.trim();

	// IPv4 validation
	var ipv4Regex = /^(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
	if (ipv4Regex.test(name)) return true;

	// DNS validation (including wildcards)
	var dnsRegex = /^(?:\*\.)?([a-zA-Z0-9]([a-zA-Z0-9\-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}$/;
	if (dnsRegex.test(name) && name.length <= 253) return true;

	return false;
}
